"""Especial productivo y nota asociada: datos del snapshot y proyectos originales."""
import json
from pathlib import Path
from visuales_presupuesto_2027 import bars, n

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'deploy/site-overlay'
REPORT = '/presupuesto/2027/desarrollo-productivo/'
NOTE = '/publicaciones/notas/comercios-ingresos-brutos-2027/'
TITLE = 'Desarrollo productivo, empleo y comercios de barrio'
NOTE_TITLE = 'Cómo un comercio puede pagar más Ingresos Brutos sin vender más'
OFFICIAL = 'https://parlamentaria.legislatura.gob.ar/pages/download.aspx?IdDoc=227616'


def summary():
    return f'''<section id="desarrollo-productivo"><span class="p27-kicker">ESPECIAL · PRODUCCIÓN Y COMERCIO</span><h2>Desarrollo productivo, empleo y comercios de barrio</h2><p>La función Industria y Comercio recibe el 0,23% del gasto proyectado. Turismo crece más que el apoyo productivo directo, mientras los incentivos fiscales requieren evaluación de resultados. Los topes de Ingresos Brutos también importan: la facturación puede superar un umbral por precios, aun sin aumentar las cantidades vendidas.</p><div class="p27-links"><a class="p27-action" href="{REPORT}">Explorar el especial productivo →</a><a href="{NOTE}">Ingresos Brutos y comercios de barrio →</a></div><p class="p27-source">Ampliación del 14/10/2026 a partir del CEDEAM–UBA, contrastada con el Mensaje, las planillas y el proyecto impositivo. Se conservan los escenarios de precios del informe integral.</p></section>'''


def shell(title, path, description, body, report=False):
    mark = '<meta name="cepoes:publication" content="report">' if report else ''
    return f'''<!doctype html><html lang="es" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — CEPOES</title><meta name="description" content="{description}">{mark}<link rel="canonical" href="https://cepoes.org{path}"><meta property="og:type" content="article"><meta property="og:title" content="{title}"><meta property="og:url" content="https://cepoes.org{path}"><meta property="article:published_time" content="2026-10-14"><meta property="article:modified_time" content="2026-10-14"><link rel="stylesheet" href="/assets/site.css"><link rel="stylesheet" href="/assets/presupuesto-2027.css"><link rel="stylesheet" href="/assets/presupuesto-2027-visuales.css"><script defer src="/assets/common-r1.js?v=259"></script></head><body data-related-tags="presupuesto,empleo,produccion,comercio,territorio">{body}</body></html>'''


def tax_example():
    chart = bars('comercio-precios', [('Ventas de referencia', 380), ('Mismas cantidades, precios +30%', 494), ('Umbral propuesto para 2027', 461.53)], 550,
                 'Las ventas pueden cruzar el umbral sólo por precios',
                 'Ejemplo hipotético: mismas cantidades vendidas y aumento uniforme de precios del 30%. Ventas anuales en millones de pesos.',
                 'Elaboración CEPOES a partir del ejemplo CEDEAM. Umbral: proyecto impositivo, Anexo I, art. 5. El 30% es un supuesto del ejemplo, no inflación observada ni pronóstico oficial.', ' M', 2)
    return chart + '''<p>Un comercio con ventas de referencia de $380 millones pasa a $494 millones si vende las mismas cantidades a precios 30% mayores. Esa facturación supera el umbral de $461.530.000 previsto en el proyecto. Para las actividades comprendidas en el artículo 5, los ingresos anuales del ejercicio anterior determinan si corresponde la alícuota general del 3% o del 5% en 2027, siempre que no exista otro tratamiento específico.</p><div class="p27-callout"><strong>De 3% a 5%: qué significa el 66,7%</strong><p>Sobre una misma base imponible hipotética de $494 millones en 2027, el 3% representa $14,82 millones y el 5%, $24,70 millones: $9,88 millones adicionales, un 66,7% más. Es una comparación entre alícuotas sobre igual base, no una variación del impuesto entre 2026 y 2027. La base imponible de 2027 puede diferir de los ingresos de 2026 usados para encuadrar al contribuyente.</p></div><p>El Mensaje impositivo propone actualizar los límites 18%. Si los precios relevantes para un negocio suben 30%, un umbral que aumenta 18% pierde 9,2% de valor real (1,18 / 1,30 − 1). Esa diferencia puede llevar a una alícuota mayor sin expansión de las cantidades vendidas. La aplicación concreta requiere identificar actividad, base imponible, exenciones y jurisdicciones.</p>'''


def generate():
    d = json.loads((SITE / 'assets/data/presupuesto-2027.json').read_text())
    functions = {r['nombre']: r for r in d['funciones']}
    selected = [functions[name] for name in ['Industria y Comercio', 'Turismo', 'Trabajo']]
    rows = ''
    for r in selected:
        old, new = r['vigente_2026_06_30'], r['proyecto_2027']
        values = [r['nombre'], '$' + n(old / 1e6), '$' + n(new / 1e6), n((new / old - 1) * 100) + '%',
                  *[n((new / old / s['factor'] - 1) * 100) + '%' for s in d['escenarios']], n(new / d['total_2027'] * 100, 2) + '%']
        rows += '<tr><th scope="row">' + values[0] + '</th>' + ''.join('<td>' + v + '</td>' for v in values[1:]) + '</tr>'
    table = '<div class="p27-table-wrap" tabindex="0" role="region" aria-label="Presupuesto productivo y empleo"><table><caption>Vigente al 30/06/2026 frente a proyecto 2027 · millones de pesos</caption><thead><tr><th scope="col">Función</th><th scope="col">2026</th><th scope="col">2027</th><th scope="col">Nominal</th><th scope="col">Real · 21,54%</th><th scope="col">Real · 23%</th><th scope="col">Peso 2027</th></tr></thead><tbody>' + rows + '</tbody></table></div>'
    spending = bars('productivo-montos', [(r['nombre'], r['proyecto_2027'] / 1e6) for r in selected], 200000,
                    'Cuánto se asigna a producción, turismo y trabajo',
                    'Funciones presupuestarias del proyecto 2027. Escala común desde cero, en millones de pesos.',
                    'Planilla 1. Las funciones agrupan gastos de distintas jurisdicciones; el gráfico no representa sólo el Ministerio de Desarrollo Económico.', ' M', 0)
    benefit_names = ['Distrito Tecnológico', 'Distrito Audiovisual y de las Artes', 'Distrito del Diseño']
    benefits = [(r['nombre'], r['millones_2027']) for r in d['gasto_tributario_seleccionado'] if r['nombre'] in benefit_names]
    benefit_chart = bars('distritos-beneficios', benefits, 200000,
                         'El Distrito Tecnológico concentra el 92,8% de estos tres regímenes',
                         'Gasto tributario estimado de los distritos Tecnológico, Audiovisual y de las Artes, y del Diseño. Millones de pesos.',
                         'Mensaje, capítulo 3.4. El denominador es el subtotal de estos tres regímenes ($207.515 millones), no todas las exenciones de la Ciudad. Son ingresos fiscales resignados estimados, no transferencias directas.', ' M', 0)
    body = f'''<main class="p27"><p class="p27-crumb"><a href="/presupuesto/2027/">Presupuesto 2027</a> / Especial productivo</p><header class="p27-hero"><div><span class="p27-kicker">100 BARRIOS · PRESUPUESTO CABA 2027</span><h1>{TITLE}</h1><p>Qué apoyo reciben la producción y el trabajo, dónde se concentran los beneficios fiscales y cómo las reglas tributarias afectan al comercio cotidiano.</p><p class="p27-source">14 de octubre de 2026 · Proyecto presentado el 30/09/2026, en tratamiento legislativo.</p></div><aside><span class="p27-kicker">LA PREGUNTA DESDE LOS BARRIOS</span><blockquote>¿Qué presupuesto sostiene el empleo y a los comercios donde vivimos?</blockquote><a href="/presupuesto/2027/">Volver al análisis integral →</a></aside></header>
<nav class="p27-index" aria-label="Capítulos del especial productivo"><a href="#contexto">Actividad y empleo</a><a href="#recursos">Recursos</a><a href="#distritos">Distritos</a><a href="#comercios">Ingresos Brutos</a><a href="#propuestas">Propuestas</a><a href="#fuentes">Fuentes</a></nav>
<section id="contexto"><span class="p27-kicker">01 · EL CONTEXTO PRODUCTIVO</span><h2>La discusión presupuestaria llega con industria y comercio en retroceso</h2><p>El Mensaje registra un crecimiento interanual del PGB porteño de 0,3% en el segundo trimestre de 2026. En ese mismo período, industria y comercio caen 1,8% y 2,2%, respectivamente. La desocupación de residentes se ubica en 7,2%. La encuesta de hogares y la de empleo formal cubren universos distintos y deben leerse con sus propios alcances.</p><p>Ingresos Brutos aporta 55,1% de los recursos totales previstos para 2027: $13,28 billones. El Mensaje informa una caída real de 6,9% en su recaudación durante el primer semestre de 2026. La capacidad fiscal depende, en buena medida, de la actividad que el presupuesto y la política tributaria deberían ayudar a sostener.</p><p class="p27-source">Mensaje, cuadros 1.1–1.4 y capítulos 2 y 3. Datos de actividad 2026 preliminares. El informe de coyuntura amplía el contexto sin atribuir estos resultados únicamente a una decisión presupuestaria.</p><a href="/publicaciones/informe-coyuntura-02-octubre-2026/">Producción y empleo bajo presión →</a></section>
<section id="recursos"><span class="p27-kicker">02 · LAS PRIORIDADES</span><h2>Turismo crece más que el apoyo productivo directo</h2>{spending}{table}<p>Industria y Comercio recibe $55.669 millones, 0,23% del gasto. Crece 6,4% real con inflación promedio estimada de 21,54%, o 5,2% con 23%. Turismo crece 20,6% o 19,1%, respectivamente. Trabajo cae 12,3% o 13,4%. Estos escenarios comparan créditos y poder de compra, mientras la cantidad y calidad de prestaciones requieren metas y seguimiento.</p><p>El Ministerio de Desarrollo Económico suma $137.129 millones, 0,57% del gasto total. La función Turismo dentro de esa jurisdicción recibe $79.161 millones, 57,7% del ministerio. La función Industria y Comercio alcanza varias jurisdicciones: Desarrollo Económico ejecutaría 89,7%, Obligaciones del Tesoro 5,5% y Hacienda 4,8%.</p><p>En la jurisdicción Desarrollo Económico, 80,9% corresponde a servicios no personales y 0,14% a bienes de uso. En la función Industria y Comercio esas proporciones son 64,3% y 0,29%. Son clasificaciones del gasto: la inversión productiva total de la Ciudad exige considerar otras jurisdicciones e instrumentos.</p><div class="p27-callout"><strong>Ejecución: montos pequeños y ritmos distintos</strong><p>Al primer semestre de 2026, Turismo había devengado 62,8% de su vigente e Industria y Comercio 46,6%, frente a 35,7% del conjunto. El ritmo relativo de estas funciones justifica revisar programas y calendarios antes de explicar sus montos por una supuesta baja ejecución.</p></div><p class="p27-source">Cuadro 2.4 y Planillas 1, 2, 3 y 8. Ministerio, función y objeto del gasto son clasificaciones distintas; sus montos no se suman entre sí.</p></section>
<section id="distritos"><span class="p27-kicker">03 · PROMOCIÓN Y TERRITORIO</span><h2>Los incentivos también deben mostrar resultados</h2>{benefit_chart}<p>El beneficio estimado del Distrito Tecnológico equivale a 3,46 veces el gasto de la función Industria y Comercio. Es una comparación de magnitudes entre instrumentos diferentes. La eliminación de una exención no permite considerar todo el importe como recaudación recuperable: las decisiones de inversión y de radicación también pueden cambiar.</p><p>Microcentro tiene una estimación de $101.402 millones y Economía del conocimiento de $42.291 millones. Este último también figura como cupo fiscal en el artículo 30 del proyecto presupuestario. Los regímenes requieren evaluación específica de inversión adicional, empleo, beneficiarios y distribución territorial.</p><p>Desde los barrios interesa conocer qué actividades se radican, a quién contratan y qué relación mantienen con proveedores locales. La ubicación de un distrito identifica el área del incentivo; los resultados sobre empleo, alquileres y valorización del suelo deben medirse con evidencia propia.</p><a href="/territorio/">Explorar el contexto de comunas y barrios →</a></section>
<section id="comercios"><span class="p27-kicker">04 · COMERCIOS DE BARRIO</span><h2>El umbral tributario puede cambiar la carga sin más ventas reales</h2>{tax_example()}<p>El proyecto de Código Fiscal propone bonificaciones del régimen simplificado para personas humanas prestadoras de servicios: 100% en las primeras tres categorías y 75% en las siguientes cinco, sujetas a reglamentación. Ese beneficio tiene un alcance específico y debe distinguirse del régimen general de comercio e industria.</p><a class="p27-action" href="{NOTE}">Leer la explicación breve sobre Ingresos Brutos →</a></section>
<section id="propuestas"><span class="p27-kicker">05 · UNA AGENDA DE 100 BARRIOS</span><h2>Apoyo productivo con presupuesto y resultados verificables</h2><p>El Mensaje anuncia Expertos PyME, herramientas digitales, líneas de apoyo financiero y aceleración, el Distrito de Inteligencia Artificial y el Parque de Innovación. Esa enumeración requiere una apertura por programas que permita identificar montos y metas.</p><ol class="p27-agenda"><li><strong>Abrir los programas antes de votar.</strong> Pedir asignaciones, beneficiarios y metas físicas del ministerio y del Ente de Turismo. El artículo 13 prevé una distribución posterior por programas.</li><li><strong>Evaluar y condicionar los incentivos.</strong> Publicar inversión y empleo adicionales, radicación y proveedores locales, con plazos de revisión de los beneficios.</li><li><strong>Proteger al comercio frente a saltos por inflación.</strong> Discutir actualización de umbrales y transiciones de alícuota, estimando previamente su costo fiscal y alcance.</li><li><strong>Vincular producción y trabajo.</strong> Articular asistencia técnica y financiamiento con universidades y formación laboral, con criterios territoriales públicos.</li><li><strong>Estudiar la captura de valorización del suelo.</strong> Evaluar instrumentos legales y costos para que parte del valor generado por intervenciones públicas financie infraestructura y apoyo productivo.</li></ol><p>Estas propuestas recogen aportes del CEDEAM y expresan una orientación editorial de CEPOES/100 Barrios. Su implementación requiere identificar programas, costos y fuentes de financiamiento.</p></section>
<section id="fuentes"><span class="p27-kicker">06 · FUENTES Y MÉTODO</span><h2>Qué usamos y cómo comparamos</h2><p>Fuente primaria: PDLEY-2026-36 del 30/09/2026, Mensaje IF-2026-43937265, cuadros 1.1–1.4 y 2.4, capítulo 3.4 y páginas 138–139; anexos IF-2026-43938160, Planillas 1, 2, 3 y 8. Tributación: PDLEY-2026-34, Anexo I artículo 5 (IF-2026-43944662) y Mensaje 40/26; PDLEY-2026-33, modificación 16 del artículo 1. Se analizan proyectos y su versión presentada.</p><p>Aporte secundario: «El desarrollo económico en el Proyecto de Presupuesto 2027 de la CABA», CEDEAM, Facultad de Ciencias Económicas, UBA, octubre de 2026. Documento elaborado por Pablo Sebastián Barreto y Sabrina Judith Canelas, bajo la dirección de Raúl Sánchez. CEPOES realizó el contraste y adaptó las comparaciones a sus escenarios de precios.</p><p>Variación real = proyecto / (vigente × factor de precios) − 1. Los factores 1,2154 y 1,23 son escenarios de inflación promedio anual 2027/2026. El 30% del ejemplo comercial es un supuesto de aumento de precios usado para explicar el umbral; corresponde a otra comparación y no se aplica al gasto presupuestario. Millones y billones se expresan según la escala española: un billón equivale a un millón de millones.</p><ul class="p27-sources"><li><a href="https://buenosaires.gob.ar/gcaba_historico/proyecto-de-ley-presupuesto-2027" target="_blank" rel="noopener">Documentación oficial del proyecto presupuestario</a>.</li><li><a href="{OFFICIAL}" target="_blank" rel="noopener">Proyecto impositivo original · expediente 3080-J-2026</a>.</li><li><a href="https://parlamentaria.legislatura.gob.ar/pages/expediente.aspx?id=142692" target="_blank" rel="noopener">Trámite del proyecto impositivo</a>.</li></ul><div class="p27-links"><a href="/presupuesto/2027/">Análisis integral y datos →</a><a href="/presupuesto/2027/salud/">Especial Salud →</a></div></section></main>'''
    note = f'''<main class="p27 p27-press"><p class="p27-crumb"><a href="/publicaciones/notas/">Notas y análisis</a> / Presupuesto 2027</p><span class="p27-kicker">100 BARRIOS · COMERCIOS DE BARRIO · 14 DE OCTUBRE DE 2026</span><h1>{NOTE_TITLE}</h1><p class="p27-lead">Si los precios aumentan más que los topes del impuesto, un comercio puede pasar a una alícuota mayor aunque venda las mismas cantidades. El proyecto porteño para 2027 permite discutir ese riesgo antes de aprobar las reglas.</p><section><h2>Qué propone el proyecto</h2><p>El artículo 5 del Anexo I del proyecto impositivo fija un umbral de $461.530.000 de ingresos brutos anuales del ejercicio anterior. Para las actividades allí comprendidas, hasta ese monto propone 3% y por encima, 5%, sujeto a tratamientos específicos. El Mensaje propone aumentar los límites 18%.</p>{tax_example()}</section><section><h2>Qué discusión proponemos desde los barrios</h2><p>Los comercios sostienen trabajo y servicios cotidianos. La discusión tributaria debería distinguir expansión real de la actividad y aumento de facturación por precios. Desde 100 Barrios proponemos evaluar mecanismos de actualización y transiciones que eviten saltos bruscos, junto con una estimación pública del costo fiscal y sus beneficiarios.</p><p>La bonificación propuesta para personas humanas prestadoras de servicios del régimen simplificado tiene un alcance diferente. Cada medida debe explicarse con sus sujetos alcanzados y condiciones.</p><p class="p27-source">Proyecto, no ley sancionada. Corte: 14/10/2026. Fuente: PDLEY-2026-34, Anexo I art. 5 y Mensaje 40/26; ejemplo inspirado en CEDEAM–UBA y recalculado por CEPOES. Se asume igual base imponible para comparar 3% y 5%; la liquidación real requiere actividad, exenciones y jurisdicciones.</p><p><a href="{OFFICIAL}" target="_blank" rel="noopener">Consultar el proyecto original →</a></p><a class="p27-action" href="{REPORT}">Leer el especial de desarrollo productivo →</a></section></main>'''
    for path, content in [(REPORT, shell(TITLE, REPORT, 'Presupuesto CABA 2027: producción, empleo, distritos económicos y comercios de barrio, con gráficos y fuentes.', body, True)),
                          (NOTE, shell(NOTE_TITLE, NOTE, 'Una explicación del umbral de Ingresos Brutos propuesto para 2027 y del efecto de los precios sobre los comercios.', note))]:
        target = SITE / path.strip('/') / 'index.html'
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content)


if __name__ == '__main__':
    generate()
